  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Emtricitabine has a mean absolute oral bioavailability of 93% in HIV patients and is reported to be unaffected by food, supporting high oral F for the query under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "GSK1322322 showed 77% absolute bioavailability after a meal in healthy volunteers, directly demonstrating high oral F in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Prucalopride has absolute oral bioavailability greater than 90% after a 2 mg oral dose, and absorption is not influenced by food, supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Asciminib is predicted to be almost completely absorbed with an absolute bioavailability of approximately 73% in humans, supporting high F for a complex oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Suvorexant has a mean absolute bioavailability of 82% in humans, supporting high oral F for a lipophilic non-nucleoside drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Elinzanetant has a moderate but dose-independent oral bioavailability of 36.7%, still well above the 20% threshold, supporting a high classification.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental evidence, with uniformly high assay-transfer scores, reports absolute oral bioavailability values well above 20% (36.7–93%), including fed-state and food-independent measurements; therefore the query is predicted to have high oral bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule; prediction relies on high-transfer analogues.",
    "Fed-state-specific data are limited to a few analogues, though those available support high or food-independent absorption."
  ],
